pragma solidity ^0.8.27;

import { IRecurringCollector } from "@graphprotocol/interfaces/contracts/horizon/IRecurringCollector.sol";
import { IGraphPayments } from "@graphprotocol/interfaces/contracts/horizon/IGraphPayments.sol";
import { OFFER_TYPE_NEW } from "@graphprotocol/interfaces/contracts/horizon/IAgreementCollector.sol";

import { RecurringCollectorSharedTest } from "./shared.t.sol";
import { MockAgreementOwner } from "./MockAgreementOwner.t.sol";

/// @notice Tests for IAgreementOwner.beforeCollection and .afterCollection in RecurringCollector._collect()
contract RecurringCollectorAfterCollectionTest is RecurringCollectorSharedTest {
    function _newApprover() internal returns (MockAgreementOwner) {
        return new MockAgreementOwner();
    }

    function _acceptUnsignedAgreement(
        MockAgreementOwner approver
    ) internal returns (IRecurringCollector.RecurringCollectionAgreement memory rca, bytes16 agreementId) {
        rca = _recurringCollectorHelper.sensibleRCA(
            IRecurringCollector.RecurringCollectionAgreement({
                deadline: uint64(block.timestamp + 1 hours),
                endsAt: uint64(block.timestamp + 365 days),
                payer: address(approver),
                dataService: makeAddr("ds"),
                serviceProvider: makeAddr("sp"),
                maxInitialTokens: 100 ether,
                maxOngoingTokensPerSecond: 1 ether,
                minSecondsPerCollection: 600,
                maxSecondsPerCollection: 3600,
                conditions: 0,
                nonce: 1,
                metadata: ""
            })
        );
        // sensibleRCA zeroes conditions unconditionally; opt back in for callback dispatch.
        rca.conditions = 2; // CONDITION_AGREEMENT_OWNER

        vm.prank(address(approver));
        _recurringCollector.offer(OFFER_TYPE_NEW, abi.encode(rca), 0);
        _setupValidProvision(rca.serviceProvider, rca.dataService);

        vm.prank(rca.dataService);
        agreementId = _recurringCollector.accept(rca, "");
    }

    /* solhint-disable graph/func-name-mixedcase */

    function test_BeforeCollection_CallbackInvoked() public {
        MockAgreementOwner approver = _newApprover();
        (IRecurringCollector.RecurringCollectionAgreement memory rca, bytes16 agreementId) = _acceptUnsignedAgreement(
            approver
        );

        skip(rca.minSecondsPerCollection);
        uint256 tokens = 1 ether;
        bytes memory data = _generateCollectData(_generateCollectParams(rca, agreementId, bytes32("col1"), tokens, 0));

        vm.prank(rca.dataService);
        _recurringCollector.collect(IGraphPayments.PaymentTypes.IndexingFee, data);

        // beforeCollection should have been called with the tokens about to be collected
        assertEq(approver.lastBeforeCollectionAgreementId(), agreementId);
        assertEq(approver.lastBeforeCollectionTokens(), tokens);
    }

    function test_BeforeCollection_CollectionSucceedsWhenCallbackReverts() public {
        MockAgreementOwner approver = _newApprover();
        (IRecurringCollector.RecurringCollectionAgreement memory rca, bytes16 agreementId) = _acceptUnsignedAgreement(
            approver
        );

        approver.setShouldRevertOnBeforeCollection(true);

        skip(rca.minSecondsPerCollection);
        uint256 tokens = 1 ether;
        bytes memory data = _generateCollectData(_generateCollectParams(rca, agreementId, bytes32("col1"), tokens, 0));

        // Collection should still succeed despite beforeCollection reverting
        vm.prank(rca.dataService);
        uint256 collected = _recurringCollector.collect(IGraphPayments.PaymentTypes.IndexingFee, data);
        assertEq(collected, tokens);

        // beforeCollection state not updated (it reverted), but afterCollection still runs
        assertEq(approver.lastBeforeCollectionAgreementId(), bytes16(0));
        assertEq(approver.lastCollectedAgreementId(), agreementId);
    }

    function test_AfterCollection_CallbackInvoked() public {
        MockAgreementOwner approver = _newApprover();
        (IRecurringCollector.RecurringCollectionAgreement memory rca, bytes16 agreementId) = _acceptUnsignedAgreement(
            approver
        );

        // Skip past minSecondsPerCollection and collect
        skip(rca.minSecondsPerCollection);
        uint256 tokens = 1 ether;
        bytes memory data = _generateCollectData(_generateCollectParams(rca, agreementId, bytes32("col1"), tokens, 0));

        vm.prank(rca.dataService);
        _recurringCollector.collect(IGraphPayments.PaymentTypes.IndexingFee, data);

        // Verify callback was invoked with correct parameters
        assertEq(approver.lastCollectedAgreementId(), agreementId);
        assertEq(approver.lastCollectedTokens(), tokens);
    }

    /// @notice With CONDITION_AGREEMENT_OWNER unset, callback dispatch is gated off
    /// regardless of whether the payer happens to be a contract. Verifies the new
    /// dispatch reads the stored flag rather than `payer.code.length`, closing the
    /// EIP-7702 surprise-callback vector.
    function test_AfterCollection_NoCallbacks_WhenAgreementOwnerConditionUnset() public {
        MockAgreementOwner approver = _newApprover();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _recurringCollectorHelper.sensibleRCA(
            IRecurringCollector.RecurringCollectionAgreement({
                deadline: uint64(block.timestamp + 1 hours),
                endsAt: uint64(block.timestamp + 365 days),
                payer: address(approver),
                dataService: makeAddr("ds-no-cb"),
                serviceProvider: makeAddr("sp-no-cb"),
                maxInitialTokens: 100 ether,
                maxOngoingTokensPerSecond: 1 ether,
                minSecondsPerCollection: 600,
                maxSecondsPerCollection: 3600,
                conditions: 0,
                nonce: 1,
                metadata: ""
            })
        );
        // sensibleRCA zeroes conditions; leave it zero to assert callbacks are skipped.

        vm.prank(address(approver));
        _recurringCollector.offer(OFFER_TYPE_NEW, abi.encode(rca), 0);
        _setupValidProvision(rca.serviceProvider, rca.dataService);
        vm.prank(rca.dataService);
        bytes16 agreementId = _recurringCollector.accept(rca, "");

        skip(rca.minSecondsPerCollection);
        uint256 tokens = 1 ether;
        bytes memory data = _generateCollectData(_generateCollectParams(rca, agreementId, bytes32("col1"), tokens, 0));

        vm.prank(rca.dataService);
        uint256 collected = _recurringCollector.collect(IGraphPayments.PaymentTypes.IndexingFee, data);
        assertEq(collected, tokens);

        // Neither callback fired — mock state is still default
        assertEq(approver.lastBeforeCollectionAgreementId(), bytes16(0), "beforeCollection must be skipped");
        assertEq(approver.lastBeforeCollectionTokens(), 0, "beforeCollection must be skipped");
        assertEq(approver.lastCollectedAgreementId(), bytes16(0), "afterCollection must be skipped");
        assertEq(approver.lastCollectedTokens(), 0, "afterCollection must be skipped");
    }

    function test_AfterCollection_CollectionSucceedsWhenCallbackReverts() public {
        MockAgreementOwner approver = _newApprover();
        (IRecurringCollector.RecurringCollectionAgreement memory rca, bytes16 agreementId) = _acceptUnsignedAgreement(
            approver
        );

        // Configure callback to revert
        approver.setShouldRevertOnCollected(true);

        skip(rca.minSecondsPerCollection);
        uint256 tokens = 1 ether;
        bytes memory data = _generateCollectData(_generateCollectParams(rca, agreementId, bytes32("col1"), tokens, 0));

        // Collection should still succeed despite callback reverting
        vm.prank(rca.dataService);
        uint256 collected = _recurringCollector.collect(IGraphPayments.PaymentTypes.IndexingFee, data);
        assertEq(collected, tokens);

        // Callback state should not have been updated (it reverted)
        assertEq(approver.lastCollectedAgreementId(), bytes16(0));
        assertEq(approver.lastCollectedTokens(), 0);
    }

    function test_Collect_Revert_WhenInsufficientCallbackGas() public {
        MockAgreementOwner approver = _newApprover();
        (IRecurringCollector.RecurringCollectionAgreement memory rca, bytes16 agreementId) = _acceptUnsignedAgreement(
            approver
        );

        skip(rca.minSecondsPerCollection);
        uint256 tokens = 1 ether;
        bytes memory data = _generateCollectData(_generateCollectParams(rca, agreementId, bytes32("col1"), tokens, 0));

        // Encode the outer collect call
        bytes memory callData = abi.encodeCall(
            _recurringCollector.collect,
            (IGraphPayments.PaymentTypes.IndexingFee, data)
        );

        // Binary-search for a gas limit that passes core collect logic but trips the
        // callback gas guard (gasleft < MAX_PAYER_CALLBACK_GAS * 64/63 + CALLBACK_GAS_OVERHEAD ≈ 1_526_810).
        // Core logic + escrow call + beforeCollection + events uses ~200k gas.
        bool triggered;
        for (uint256 gasLimit = 1_700_000; gasLimit > 1_500_000; gasLimit -= 10_000) {
            uint256 snap = vm.snapshotState();
            vm.prank(rca.dataService);
            (bool success, bytes memory returnData) = address(_recurringCollector).call{ gas: gasLimit }(callData);
            if (!success && returnData.length >= 4) {
                bytes4 selector;
                assembly {
                    selector := mload(add(returnData, 32))
                }
                if (selector == IRecurringCollector.RecurringCollectorInsufficientCallbackGas.selector) {
                    triggered = true;
                    assertTrue(vm.revertToState(snap));
                    break;
                }
            }
            assertTrue(vm.revertToState(snap));
        }
        assertTrue(triggered, "Should have triggered InsufficientCallbackGas at some gas limit");
    }

    /// @notice The CALLBACK_GAS_OVERHEAD precheck also guards the eligibility staticcall
    /// (first of three callback prechecks). Binary-search for a gas limit that reaches the
    /// eligibility precheck and trips it, confirming the buffer logic applies there too.
    function test_Collect_Revert_WhenInsufficientCallbackGas_EligibilityPrecheck() public {
        MockAgreementOwner approver = _newApprover();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _recurringCollectorHelper.sensibleRCA(
            IRecurringCollector.RecurringCollectionAgreement({
                deadline: uint64(block.timestamp + 1 hours),
                endsAt: uint64(block.timestamp + 365 days),
                payer: address(approver),
                dataService: makeAddr("ds"),
                serviceProvider: makeAddr("sp"),
                maxInitialTokens: 100 ether,
                maxOngoingTokensPerSecond: 1 ether,
                minSecondsPerCollection: 600,
                maxSecondsPerCollection: 3600,
                conditions: 0,
                nonce: 1,
                metadata: ""
            })
        );
        rca.conditions = 1; // CONDITION_ELIGIBILITY_CHECK — activates the eligibility precheck first

        vm.prank(address(approver));
        _recurringCollector.offer(OFFER_TYPE_NEW, abi.encode(rca), 0);
        _setupValidProvision(rca.serviceProvider, rca.dataService);

        vm.prank(rca.dataService);
        bytes16 agreementId = _recurringCollector.accept(rca, "");

        skip(rca.minSecondsPerCollection);
        uint256 tokens = 1 ether;
        bytes memory data = _generateCollectData(_generateCollectParams(rca, agreementId, bytes32("col1"), tokens, 0));
        bytes memory callData = abi.encodeCall(
            _recurringCollector.collect,
            (IGraphPayments.PaymentTypes.IndexingFee, data)
        );

        // With eligibility enabled, three sequential callbacks each need the buffer. The test
        // confirms at least one (the first, eligibility) trips InsufficientCallbackGas.
        bool triggered;
        for (uint256 gasLimit = 1_700_000; gasLimit > 1_500_000; gasLimit -= 10_000) {
            uint256 snap = vm.snapshotState();
            vm.prank(rca.dataService);
            (bool success, bytes memory returnData) = address(_recurringCollector).call{ gas: gasLimit }(callData);
            if (!success && returnData.length >= 4) {
                bytes4 selector;
                // solhint-disable-next-line no-inline-assembly
                assembly {
                    selector := mload(add(returnData, 32))
                }
                if (selector == IRecurringCollector.RecurringCollectorInsufficientCallbackGas.selector) {
                    triggered = true;
                    assertTrue(vm.revertToState(snap));
                    break;
                }
            }
            assertTrue(vm.revertToState(snap));
        }
        assertTrue(triggered, "eligibility precheck must trip InsufficientCallbackGas under tight gas");
    }

    function test_AfterCollection_NotCalledForEOAPayer(FuzzyTestCollect calldata fuzzy) public {
        // Use standard ECDSA-signed path (EOA payer, no contract)
        (IRecurringCollector.RecurringCollectionAgreement memory acceptedRca, , , ) = _sensibleAuthorizeAndAccept(
            fuzzy.fuzzyTestAccept
        );

        (bytes memory data, uint256 collectionSeconds, uint256 tokens) = _generateValidCollection(
            acceptedRca,
            fuzzy.collectParams,
            fuzzy.collectParams.tokens, // reuse as skip seed
            fuzzy.collectParams.tokens
        );

        skip(collectionSeconds);
        // Should succeed without any callback issues (EOA has no code)
        vm.prank(acceptedRca.dataService);
        uint256 collected = _recurringCollector.collect(_paymentType(fuzzy.unboundedPaymentType), data);
        assertEq(collected, tokens);
    }

    /* solhint-enable graph/func-name-mixedcase */
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import { IRecurringCollector } from "@graphprotocol/interfaces/contracts/horizon/IRecurringCollector.sol";
import {
    IAgreementCollector,
    OFFER_TYPE_NEW,
    OFFER_TYPE_UPDATE,
    REGISTERED,
    ACCEPTED,
    NOTICE_GIVEN,
    SETTLED,
    BY_PROVIDER,
    UPDATE,
    VERSION_CURRENT,
    VERSION_NEXT
} from "@graphprotocol/interfaces/contracts/horizon/IAgreementCollector.sol";

import { RecurringCollectorSharedTest } from "./shared.t.sol";
import { MockAgreementOwner } from "./MockAgreementOwner.t.sol";

/// @notice State-flag semantics for AgreementDetails returned by offer() and getAgreementDetails().
/// Pins down two properties:
///   1. offer() reports the same lifecycle state as getAgreementDetails() for the queried version
///      (REGISTERED, ACCEPTED, UPDATE, NOTICE_GIVEN, BY_*, SETTLED) — not just the version-specific
///      bits.
///   2. SETTLED is per-version: VERSION_CURRENT scopes to active terms, VERSION_NEXT to pending —
///      a non-zero claim on one version must not suppress SETTLED on the other.
contract RecurringCollectorAgreementDetailsStateTest is RecurringCollectorSharedTest {
    /* solhint-disable graph/func-name-mixedcase */

    function _makeRca(address payer) internal returns (IRecurringCollector.RecurringCollectionAgreement memory) {
        return
            _recurringCollectorHelper.sensibleRCA(
                IRecurringCollector.RecurringCollectionAgreement({
                    deadline: uint64(block.timestamp + 1 hours),
                    endsAt: uint64(block.timestamp + 365 days),
                    payer: payer,
                    dataService: makeAddr("ds"),
                    serviceProvider: makeAddr("sp"),
                    maxInitialTokens: 100 ether,
                    maxOngoingTokensPerSecond: 1 ether,
                    minSecondsPerCollection: 600,
                    maxSecondsPerCollection: 3600,
                    conditions: 0,
                    nonce: 1,
                    metadata: ""
                })
            );
    }

    function _makeRcau(
        bytes16 agreementId,
        IRecurringCollector.RecurringCollectionAgreement memory rca,
        uint64 deadline
    ) internal pure returns (IRecurringCollector.RecurringCollectionAgreementUpdate memory) {
        return
            IRecurringCollector.RecurringCollectionAgreementUpdate({
                agreementId: agreementId,
                deadline: deadline,
                endsAt: rca.endsAt + 30 days,
                maxInitialTokens: rca.maxInitialTokens,
                maxOngoingTokensPerSecond: rca.maxOngoingTokensPerSecond * 2,
                minSecondsPerCollection: rca.minSecondsPerCollection,
                maxSecondsPerCollection: rca.maxSecondsPerCollection,
                conditions: 0,
                nonce: 1,
                metadata: ""
            });
    }

    function _acceptUnsigned(
        MockAgreementOwner approver,
        IRecurringCollector.RecurringCollectionAgreement memory rca
    ) internal returns (bytes16) {
        vm.prank(address(approver));
        _recurringCollector.offer(OFFER_TYPE_NEW, abi.encode(rca), 0);
        _setupValidProvision(rca.serviceProvider, rca.dataService);
        vm.prank(rca.dataService);
        return _recurringCollector.accept(rca, "");
    }

    // ──────────────────────────────────────────────────────────────────────
    // offer() return state mirrors getAgreementDetails()
    // ──────────────────────────────────────────────────────────────────────

    /// @notice Fresh offer(NEW) on a never-seen agreement returns REGISTERED only.
    function test_OfferNew_FreshOffer_State_Registered() public {
        MockAgreementOwner approver = new MockAgreementOwner();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _makeRca(address(approver));

        vm.prank(address(approver));
        IAgreementCollector.AgreementDetails memory details = _recurringCollector.offer(
            OFFER_TYPE_NEW,
            abi.encode(rca),
            0
        );

        assertEq(details.state, REGISTERED, "fresh offer(NEW): REGISTERED only");
    }

    /// @notice Fresh offer(UPDATE) on an accepted agreement returns REGISTERED|UPDATE only.
    function test_OfferUpdate_FreshOffer_State_RegisteredUpdate() public {
        MockAgreementOwner approver = new MockAgreementOwner();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _makeRca(address(approver));
        bytes16 agreementId = _acceptUnsigned(approver, rca);

        IRecurringCollector.RecurringCollectionAgreementUpdate memory rcau = _makeRcau(
            agreementId,
            rca,
            uint64(block.timestamp + 1 hours)
        );

        vm.prank(address(approver));
        IAgreementCollector.AgreementDetails memory details = _recurringCollector.offer(
            OFFER_TYPE_UPDATE,
            abi.encode(rcau),
            0
        );

        assertEq(details.state, REGISTERED | UPDATE, "fresh offer(UPDATE): REGISTERED|UPDATE");
    }

    /// @notice Re-offering an already-accepted RCA hits the idempotent path and must report
    /// ACCEPTED — the offered version is the active accepted terms.
    function test_OfferNew_AfterAccept_State_RegisteredAccepted() public {
        MockAgreementOwner approver = new MockAgreementOwner();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _makeRca(address(approver));
        _acceptUnsigned(approver, rca);

        vm.prank(address(approver));
        IAgreementCollector.AgreementDetails memory details = _recurringCollector.offer(
            OFFER_TYPE_NEW,
            abi.encode(rca),
            0
        );

        assertEq(details.state, REGISTERED | ACCEPTED, "re-offer(NEW) after accept: REGISTERED|ACCEPTED");
    }

    /// @notice Re-offering an already-applied RCAU hits the idempotent path; since the RCAU is
    /// now the active terms, the queried version is CURRENT, so state is REGISTERED|ACCEPTED|UPDATE.
    function test_OfferUpdate_AfterApply_State_RegisteredAcceptedUpdate() public {
        MockAgreementOwner approver = new MockAgreementOwner();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _makeRca(address(approver));
        bytes16 agreementId = _acceptUnsigned(approver, rca);

        IRecurringCollector.RecurringCollectionAgreementUpdate memory rcau = _makeRcau(
            agreementId,
            rca,
            uint64(block.timestamp + 1 hours)
        );
        vm.prank(address(approver));
        _recurringCollector.offer(OFFER_TYPE_UPDATE, abi.encode(rcau), 0);
        vm.prank(rca.dataService);
        _recurringCollector.update(rcau, "");

        vm.prank(address(approver));
        IAgreementCollector.AgreementDetails memory details = _recurringCollector.offer(
            OFFER_TYPE_UPDATE,
            abi.encode(rcau),
            0
        );

        assertEq(
            details.state,
            REGISTERED | ACCEPTED | UPDATE,
            "re-offer(UPDATE) after apply: REGISTERED|ACCEPTED|UPDATE"
        );
    }

    /// @notice Re-offering an RCA after the agreement was canceled by the service provider must
    /// surface NOTICE_GIVEN|BY_PROVIDER (and SETTLED, since active claim is zero in this state).
    function test_OfferNew_AfterProviderCancel_State_FullyDecorated() public {
        MockAgreementOwner approver = new MockAgreementOwner();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _makeRca(address(approver));
        bytes16 agreementId = _acceptUnsigned(approver, rca);

        vm.prank(rca.dataService);
        _recurringCollector.cancel(agreementId, IRecurringCollector.CancelAgreementBy.ServiceProvider);

        vm.prank(address(approver));
        IAgreementCollector.AgreementDetails memory details = _recurringCollector.offer(
            OFFER_TYPE_NEW,
            abi.encode(rca),
            0
        );

        assertEq(
            details.state,
            REGISTERED | ACCEPTED | NOTICE_GIVEN | BY_PROVIDER | SETTLED,
            "re-offer(NEW) after provider cancel: REGISTERED|ACCEPTED|NOTICE_GIVEN|BY_PROVIDER|SETTLED"
        );
    }

    // ──────────────────────────────────────────────────────────────────────
    // SETTLED is per-version (active vs pending scoping)
    // ──────────────────────────────────────────────────────────────────────

    /// @notice Pending RCAU past its deadline contributes 0 to claim. With per-version SETTLED
    /// scoping, VERSION_NEXT reports SETTLED even though the active terms still have claim.
    /// Pre-fix (unscoped getMaxNextClaim) would have suppressed SETTLED here.
    function test_GetAgreementDetails_VersionNext_SettledIndependentOfActive() public {
        MockAgreementOwner approver = new MockAgreementOwner();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _makeRca(address(approver));
        bytes16 agreementId = _acceptUnsigned(approver, rca);

        uint64 rcauDeadline = uint64(block.timestamp + 1 hours);
        IRecurringCollector.RecurringCollectionAgreementUpdate memory rcau = _makeRcau(agreementId, rca, rcauDeadline);
        vm.prank(address(approver));
        _recurringCollector.offer(OFFER_TYPE_UPDATE, abi.encode(rcau), 0);

        // Past pending deadline — pending claim is 0, but active claim still grows.
        vm.warp(rcauDeadline + 1);

        IAgreementCollector.AgreementDetails memory next = _recurringCollector.getAgreementDetails(
            agreementId,
            VERSION_NEXT
        );
        IAgreementCollector.AgreementDetails memory current = _recurringCollector.getAgreementDetails(
            agreementId,
            VERSION_CURRENT
        );

        assertEq(next.state & SETTLED, SETTLED, "VERSION_NEXT: SETTLED set when pending claim is 0");
        assertEq(current.state & SETTLED, 0, "VERSION_CURRENT: SETTLED not set when active claim is non-zero");
    }

    /// @notice Active terms past their offer deadline (still NotAccepted) have 0 active claim.
    /// With per-version scoping, VERSION_CURRENT reports SETTLED even though a fresh pending
    /// update still has non-zero claim. Pre-fix, the pending claim would have masked SETTLED.
    function test_GetAgreementDetails_VersionCurrent_SettledIndependentOfPending() public {
        MockAgreementOwner approver = new MockAgreementOwner();
        IRecurringCollector.RecurringCollectionAgreement memory rca = _makeRca(address(approver));
        vm.prank(address(approver));
        IAgreementCollector.AgreementDetails memory offered = _recurringCollector.offer(
            OFFER_TYPE_NEW,
            abi.encode(rca),
            0
        );
        bytes16 agreementId = offered.agreementId;

        // Pending update with a far-future deadline — its claim stays non-zero after the warp.
        IRecurringCollector.RecurringCollectionAgreementUpdate memory rcau = _makeRcau(
            agreementId,
            rca,
            uint64(block.timestamp + 30 days)
        );
        vm.prank(address(approver));
        _recurringCollector.offer(OFFER_TYPE_UPDATE, abi.encode(rcau), 0);

        // Past the RCA's offer deadline — active claim drops to 0 (state still NotAccepted, no
        // valid pre-acceptance offer).
        vm.warp(rca.deadline + 1);

        IAgreementCollector.AgreementDetails memory current = _recurringCollector.getAgreementDetails(
            agreementId,
            VERSION_CURRENT
        );
        IAgreementCollector.AgreementDetails memory next = _recurringCollector.getAgreementDetails(
            agreementId,
            VERSION_NEXT
        );

        assertEq(current.state & SETTLED, SETTLED, "VERSION_CURRENT: SETTLED set when active claim is 0");
        assertEq(next.state & SETTLED, 0, "VERSION_NEXT: SETTLED not set when pending claim is non-zero");
    }
}

